S=/tmp/claude-0/-home-user-guidebook/f8d4d6c2-8f72-53c6-8e31-d3258750c5f6/scratchpad; ls -l $S/adjudication*.md $S/antagonist*.md $S/ecosystem-census.md $S/claude-md-audit.md 2>&1 | sed 's#'$S'/##'
echo "--- ledger OD status lines (latest status per OD id)"
python3 - <<'PY'
import re,collections
t=open('references/project-standards.md',encoding='utf-8').read().split('\n')
last={}
for i,l in enumerate(t,1):
    m=re.match(r'^(OD-\d+[a-z]?(?:\s*\([^)]*\))?)\s+STATUS:\s*(.+)$',l.strip())
    if m:
        k=re.match(r'OD-\d+[a-z]?',m.group(1)).group(0); last[k]=(m.group(2).strip(),i)
c=collections.Counter(v[0] for v in last.values())
for k,v in c.most_common(): print(v,k)
print('distinct OD ids with a STATUS line:',len(last))
for k,(s,i) in sorted(last.items(),key=lambda x:int(re.sub(r'\D','',x[0]))):
    if 'REFERRED' in s or 'OPEN' in s.upper() or 'HELD' in s.upper(): print(k,s,'L%d'%i)
PY
echo "--- DB: gaps and decisions"
python3 - <<'PY'
import sqlite3
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
for t in ('gaps','decisions'):
    cols=[r[1] for r in c.execute(f'pragma table_info({t})')]
    print(t,cols[:14])
try:
    print(c.execute("select status,count(*) from gaps group by 1").fetchall())
except Exception as e: print('gaps',e)
try:
    print(c.execute("select review_status,count(*) from decisions group by 1").fetchall())
except Exception as e: print('decisions',e)
PY

